menu.h:
class menu {
public:
  menu(apvector<apstring> v);
  void display();
  int choice();
private:
  apvector<apstring> items;
  apstring choices;
};
menu.cpp
#include "menu.h"
menu::menu(apvector<apstring> v) {
  items = v;
  choices="";
  for (int i=0; i<v.length(); ++i)
  {
    for (int j=0; j<v[i].length();
                            ++j) {
      if (<*1>) {
        choices+=v[i][j];
        items[i]=v[i].substr(0,j)+
             '*'+v[i][j]+'*'+
             v[i].substr(j+1,
               v[i].length()-j-1);
        break;
      }
    }
  }
}
void menu::display() {
  for (int i=0; i<items.length();
                           ++i)
    cout << items[i] << endl;
}
int menu::choice() {
  // reads a character from the
  // user and returns the number
  // of the corresponding menu
  // item
}

