template <class itemType>
void sort(apvector<itemType> & A){
  sort1(A,0,A.length()-1);
}
template <class itemType>
void sort1(apvector<itemType> & A,
           int x, int y) {
  int z=(x+y)/2;
  if (z-x>=1) sort1(A,x,z); /**/
  if (y-z>1) sort1(A,z+1,y);
  apvector<itemType>
                    B(y-x+1,A[z]);
  int i=x,j=z+1,k=0;
  while (i<=z && j<=y)
    if (A[i]<A[j]) B[k++]=A[i++];
    else B[k++]=A[j++];
  while (i<=z) B[k++]=A[i++];
  while (j<=y) B[k++]=A[j++];
  for (k=0; k<=y-x; ++k)
    A[x+k]=B[k];
}

template <class itemType>
void sort(apvector<itemType> & A){
  sort1(A,0,A.length()-1);
}
template <class itemType>
void sort1(apvector<itemType> & A,
           int x, int y) {
