int partition(int A[], int r,
                          int s) {
  // rearranges elements of A
  // from index r to s-1,
  // so that all elements before
  // the element at A[r] come
  // first, then the element 
  // originally at A[r], then
  // all the other elements 
  // returns the new index of the
  // original A[r]
}
int mystery(int A[], int length) {
  int mid=length/2;
  int part;
  int i=0, j=length;
  while ((part=partition(A,i,j))!=
                            mid) {
    if (part<mid) i=part+1;
    else j=part-1;
  }
  return A[mid];
}
